insert into public.shifts (id, data) values
  ('shift_101', '{"id":"shift_101","hospitalId":"hosp_st_francis","hospitalName":"St. Francis Medical Center ED","facilityLocation":"3630 E Imperial Hwy, Lynwood, CA","lat":33.9288,"lng":-118.204,"distanceMiles":8.5,"specialty":"Emergency Medicine","title":"High-Volume Community ER Nocturnist","department":"Emergency Department","hourlyRate":185,"totalPay":2220,"shiftType":"Night Shift","startTime":"19:00","endTime":"07:00","date":"2026-08-15","durationHours":12,"pgyRequirement":["PGY-2","PGY-3","PGY-4","Fellow"],"requiredDocIds":["pd_letter","state_license","dea_certificate","acls_card","malpractice_cert","tb_immunization"],"description":"Community ED nocturnist coverage in Level 2 Trauma center. ESI Level 2-4 management, rapid laceration repair, bedside ultrasound, and procedural sedation. Attending backup on site.","malpracticeIncluded":true,"restCallRoomAvailable":true,"mealStipend":true,"urgency":"High Demand","spotsAvailable":2}'::jsonb),
