  ('shift_105', '{"id":"shift_105","hospitalId":"hosp_glendale_adv","hospitalName":"Glendale Adventist ER Division","facilityLocation":"1509 Wilson Terrace, Glendale, CA","lat":34.1481,"lng":-118.2325,"distanceMiles":7.8,"specialty":"Emergency Medicine","title":"Community ER Overnight Attending Relief","department":"Emergency Department","hourlyRate":175,"totalPay":2100,"shiftType":"Night Shift","startTime":"20:00","endTime":"08:00","date":"2026-08-17","durationHours":12,"pgyRequirement":["PGY-2","PGY-3","PGY-4","Fellow"],"requiredDocIds":["pd_letter","state_license","dea_certificate","acls_card","malpractice_cert","tb_immunization","mask_fit"],"description":"Overnight ER coverage. High-volume chest pain protocols, acute strokes, and trauma stabilization. Double coverage with senior APP.","malpracticeIncluded":true,"restCallRoomAvailable":true,"mealStipend":true,"urgency":"High Demand","spotsAvailable":1}'::jsonb),
